import 'dart:convert';
import 'package:flutter/material.dart';

/// Pre-decoded image bytes for assets that may not load via Image.asset on web.
class AppImages {
  AppImages._();

  static final _mahilaKisanBytes = base64Decode('');
  static final _carrotMascotBytes = base64Decode('');

  static Widget get mahilaKisan => Image.memory(
        _mahilaKisanBytes,
        fit: BoxFit.contain,
        errorBuilder: (context, error, stackTrace) =>
            const Icon(Icons.person, color: Colors.amberAccent, size: 40),
      );

  static Widget get carrotMascot => Image.memory(
        _carrotMascotBytes,
        fit: BoxFit.contain,
        errorBuilder: (context, error, stackTrace) =>
            const Icon(Icons.eco, color: Colors.green, size: 40),
      );
}
